      pipes: { cols: ['colour', 'width', 'points'], rows: (ol.pipes || []).slice(0, 200) },
      pills: { cols: ['x', 'y', 'w', 'h', 'fill', 'ring', 'ring_width'], rows: (ol.pills || []).slice(0, 200) },
